import Footer from "../components/Footer";
import Header from "../components/Header";

import "../styles/noticiass.css";

export default function Noticias() {
  return (
    <>
      <Header />

      <section className="noticias-hero">
        <h1>NOTÍCIAS</h1>
        <p>Fique por dentro das últimas novidades.</p>
      </section>

      <section className="noticias-container">
        <div className="noticia-card">
          <img src="data:image/jpeg;base64," alt="" />

          <div className="noticia-info">


            <h2>
              Festival reúne milhares de pessoas
              neste final de semana
            </h2>

            <p>
              Confira os principais destaques do evento.
            </p>

            <button>Ler mais</button>
          </div>
        </div>

        <div className="noticia-card">
          <img src="data:image/jpeg;base64," alt="" />

          <div className="noticia-info">
            <span>Entretenimento</span>

            <h2>
              Fique de Olho nos Horarios do evento
            </h2>

            <p>
              Sabado  das 10h ás 21h
              <br/>
              Domingo das 09h as 20h
            </p>

            <button>Ler mais</button>
          </div>
        </div>
      </section>

      <Footer />
    </>
  );
}
